INSERT INTO `faq` (`id_faq`, `question`, `reponse`, `categorie`, `ordre`, `est_publiee`, `id_page_associee`) VALUES (8,'What is African Green Farmers (A.G.F) Limited?','African Green Farmers (A.G.F) Limited is a Zambian agro-industrial investment company focused on phytopharmaceutical production, sustainable agriculture, and nutritional advisory services.','General',0,1,NULL),(9,'Where is A.G.F headquartered?','A.G.F is headquartered in Lusaka, Zambia, with operations across Southern Africa.','General',0,1,NULL),(10,'What is the Tax Identification Number (TPIN)?','The TPIN for African Green Farmers (A.G.F) Limited is 2003675243.','General',0,1,NULL),(11,'What is the total investment amount?','The total investment projection for A.G.F is structured across multiple phases, with detailed projections available in our investment documentation.','Investment',0,1,NULL),(12,'What type of financing is being sought?','A.G.F is seeking strategic investors and partners for equity and debt financing across its agro-industrial projects.','Investment',0,1,NULL),(13,'What is the investment license number?','A.G.F holds Investment License Number ZDA/59004/10/2025 issued by the Zambia Development Agency.','Investment',0,1,NULL),(14,'What are A.G.F main products?','A.G.F produces phytopharmaceutical products, organic agricultural products, and nutritional supplements from locally sourced functional plants.','Products',0,1,NULL),(15,'Where is the pilot production site?','The pilot production facility is located in Zambia, featuring a modern PhytoMed processing unit.','Products',0,1,NULL),(16,'What is the total project duration?','The project is structured in multiple phases spanning several years, with detailed timelines available in our strategic plan.','Project',0,1,NULL),(17,'What are A.G.F strategic business units?','A.G.F operates through multiple Strategic Business Units (SBUs) including PhytoMed, organic farming, and digital advisory services.','Project',0,1,NULL),(18,'What is the SBLC mechanism?','The Standby Letter of Credit (SBLC) mechanism is used to secure investment commitments and facilitate international trade transactions.','Project',0,1,NULL),(19,'What is the total land area?','A.G.F controls extensive agricultural land across Zambia for cultivation of medicinal plants and organic crops.','Project',0,1,NULL);
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
UNLOCK TABLES;

