INSERT INTO `unites_affaires` (`id`, `uuid`, `code`, `nom`, `description`, `slogan`, `logo`, `slug`, `ordre`, `est_actif`, `created_at`, `updated_at`) VALUES (1,'c48f2e64-ad6f-11f1-a775-9c7bef735b1f','ABI_IND','ABIPROF Industries','Agro-food and nutraceutical industrial manufacturing division. Integrated production platform manufacturing at least 12 standardized, clean-label flagship products.','Advanced industrial manufacturing','attachments/Unites/abiprof-industries-logo-alt.png','abiprof-industries',1,1,'2026-09-10 23:31:37','2026-10-01 19:20:23'),(2,'c48f31d0-ad6f-11f1-a775-9c7bef735b1f','ABI_EST','ABIPROF Agro-Estates','Integrated agricultural production systems across more than 2,000 hectares, including regenerative agriculture, Hydraulic Ram Pump irrigation and a contract-farming programme with 5,000+ farmers.','Integrated regenerative agriculture','attachments/Unites/abiprof-agro-estates-logo-alt.png','abiprof-agro-estates',2,1,'2026-09-10 23:31:37','2026-10-01 19:20:23'),(3,'c48f33d5-ad6f-11f1-a775-9c7bef735b1f','ABI_LST','ABIPROF Livestock Bioresource','Dairy cattle (150 head initial) and swine (150 head initial) farming systems, organic bioinput production, biological resource recovery and biocontrol systems.','Livestock and biological resource recovery','attachments/Unites/abiprof-livestock-bioresources-logo.png','abiprof-livestock-bioresource',3,1,'2026-09-10 23:31:37','2026-10-01 19:20:23'),(4,'c48f350a-ad6f-11f1-a775-9c7bef735b1f','SER_LAB','SERIQA LABORATORIES','Advanced scientific and analytical centre supporting authentication, molecular discovery, structural analysis, elemental and bioanalytical characterization, microbiology, standardization, formulation, quality control, stability, technology transfer and product-release support for ANINOVA INDUSTRIES.','Scientific research and innovation','attachments/Unites/ceriqa-laboratories-logo.png','seriqa-laboratories',4,1,'2026-09-10 23:31:37','2026-10-01 19:20:23'),(5,'c48f373f-ad6f-11f1-a775-9c7bef735b1f','NHS_SUP','Natural Health Food Supermarkets','Natural health supermarket network for retail commercialization of nutraceutical, fortified and organic food products.','Natural health retail','attachments/Unites/natural-health-supermarkets-logo.jpeg','natural-health-supermarkets',5,1,'2026-09-10 23:31:37','2026-10-01 19:20:23');
/*!40000 ALTER TABLE `unites_affaires` ENABLE KEYS */;
